import numpy as np
import matplotlib.pyplot as plt

# Define convex and non-convex functions
def convex_fn(x, y):
    """Convex: f(x,y) = x^2 + y^2"""
    return x**2 + y**2

def nonconvex_fn(x, y):
    """Non-convex: f(x,y) = sin(x)*cos(y) + 0.1*(x^2+y^2)"""
    return np.sin(x) * np.cos(y) + 0.1 * (x**2 + y**2)

def gradient_descent(fn_grad, x0, lr=0.1, steps=50):
    path = [x0.copy()]
    x = x0.copy()
    for _ in range(steps):
        x = x - lr * fn_grad(x)
        path.append(x.copy())
    return np.array(path)

def grad_convex(x):
    return 2 * x

def grad_nonconvex(x):
    return np.array([
        np.cos(x[0]) * np.cos(x[1]) + 0.2 * x[0],
        -np.sin(x[0]) * np.sin(x[1]) + 0.2 * x[1]
    ])

# Run GD from multiple starts on the non-convex surface
starts = [np.array([3.0, 2.0]), np.array([-3.0, 2.5]), np.array([1.5, -2.0])]
paths_nc = [gradient_descent(grad_nonconvex, s, lr=0.05) for s in starts]

print(f"Convex fn global minimum: {convex_fn(0, 0):.4f}")
print("Non-convex: GD converges to different minima depending on start:")
for i, path in enumerate(paths_nc):
    final = path[-1]
    print(f"  Start {starts[i]}: converged to {final}, f={nonconvex_fn(*final):.4f}")

import torch

class SAM(torch.optim.Optimizer):
    """Sharpness-Aware Minimization (Foret et al. 2021)."""

    def __init__(self, params, base_optimizer_cls, rho=0.05, **kwargs):
        defaults = dict(rho=rho, **kwargs)
        super().__init__(params, defaults)
        self.base_optimizer = base_optimizer_cls(self.param_groups, **kwargs)
        self.param_groups = self.base_optimizer.param_groups

    @torch.no_grad()
    def first_step(self, zero_grad=False):
        """Climb to the worst-case perturbation point θ + ε̂."""
        grad_norm = self._grad_norm()
        for group in self.param_groups:
            scale = group["rho"] / (grad_norm + 1e-12)
            for p in group["params"]:
                if p.grad is None:
                    continue
                e_w = p.grad * scale.to(p)
                p.add_(e_w)
                self.state[p]["e_w"] = e_w
        if zero_grad:
            self.zero_grad()

    @torch.no_grad()
    def second_step(self, zero_grad=False):
        """Restore θ, then apply base optimizer step using perturbed gradient."""
        for group in self.param_groups:
            for p in group["params"]:
                if p.grad is None:
                    continue
                p.sub_(self.state[p]["e_w"])
        self.base_optimizer.step()
        if zero_grad:
            self.zero_grad()

    def _grad_norm(self):
        device = self.param_groups[0]["params"][0].device
        norms = [p.grad.norm(2).to(device)
                 for g in self.param_groups for p in g["params"]
                 if p.grad is not None]
        return torch.stack(norms).norm(2)

# Quick usage demo
torch.manual_seed(42)
net = torch.nn.Linear(4, 1)
opt = SAM(net.parameters(), torch.optim.SGD, rho=0.05, lr=0.05)
X, y = torch.randn(32, 4), torch.randn(32, 1)
loss_fn = torch.nn.MSELoss()
for step in range(4):
    loss = loss_fn(net(X), y)
    loss.backward()
    opt.first_step(zero_grad=True)
    loss_fn(net(X), y).backward()
    opt.second_step(zero_grad=True)
    print(f"Step {step+1}: loss={loss.item():.4f}")
